actions.script:
def p = ec.web.parameters
try {
    if (!p.productId) { ec.web.sendJsonResponse([success:false, error:'Missing product']); return }
    // Org isolation (ZE-SEC-JSON): this write endpoint must only mutate THIS org's products.
    // The MANTLE_ACTIVE_ORG filter does NOT apply in a transition, so verify ownership explicitly
    // (super-admin exempt). Prevents cross-tenant price/MRP tampering via a forged productId.
    def _ppAo = ec.user.getPreference('ACTIVE_ORGANIZATION')
    def _ppOwn = ec.entity.find("mantle.product.Product").condition("productId", p.productId).disableAuthz().one()?.ownerPartyId
    if (!_ppOwn) { ec.web.sendJsonResponse([success:false, error:'Product not found.']); return }
    if (!ec.user.isInGroup('ADMIN')) {
        if (!_ppAo || _ppAo == '_NA_' || _ppOwn != _ppAo) { ec.web.sendJsonResponse([success:false, error:'You do not have access to this product.']); return }
    }
    def extraId = (p.extraModeId ?: 'EMPLOYEE').toString()
    def extraMode = ec.entity.find('zenith.erp.pos.PosSalesMode').condition('salesModeId',extraId).one()
    if (!extraMode || extraMode.isActive != 'Y' || extraMode.priceSource != 'PpsFixedProduct' || extraId == 'WHOLESALE' || (extraMode.organizationPartyId && extraMode.organizationPartyId != _ppOwn)) {
        ec.web.sendJsonResponse([success:false, error:'Choose an available fixed-price sales mode.']); return
    }
    // ZE-INV-001 f/u: reject negative prices with a clear message. (A negative would otherwise be
    // silently dropped -> set#PosModePrice treats price<=0 as "clear the mode".) Blank/0 = clear.
    def parseBd = { v -> if (v == null || v.toString().trim() == '') return null; try { return v.toString().trim() as BigDecimal } catch (ex) { return null } }
    def extraRaw = p.containsKey('extraPrice') ? p.extraPrice : p.employeePrice
    def rtBd = parseBd(p.retailPrice); def wsBd = parseBd(p.wholesalePrice); def emBd = parseBd(extraRaw); def thBd = parseBd(p.wholesaleThreshold)
    if ([p.retailPrice,p.wholesalePrice,extraRaw,p.wholesaleThreshold].any { it != null && it.toString().trim() && parseBd(it) == null }) {
        ec.web.sendJsonResponse([success:false, error:'Enter a valid numeric price.']); return
    }
    if (thBd != null && (thBd < 0G || thBd.stripTrailingZeros().scale() > 0)) { ec.web.sendJsonResponse([success:false, error:'Auto-wholesale quantity must be a non-negative whole number.']); return }
    if ((rtBd != null && rtBd < 0G) || (wsBd != null && wsBd < 0G) || (emBd != null && emBd < 0G)) {
        ec.web.sendJsonResponse([success:false, error:"Prices can't be negative — enter a positive amount (or leave blank to clear)."]); return
    }
    // Retail price = product MRP; only update when a positive value was entered.
    if (p.retailPrice != null && p.retailPrice.toString().trim() != '')
        ec.service.sync().name("zenith.pos.PosServices.set#PosModePrice")
            .parameters([productId:p.productId, salesModeId:'RETAIL', price:(p.retailPrice as BigDecimal)]).call()
    // Wholesale / Custom: empty clears the price (=> product blocked in that mode).
    // wholesaleThreshold (optional): auto-switch a retail line to the wholesale price at this qty.
    ec.service.sync().name("zenith.pos.PosServices.set#PosModePrice")
        .parameters([productId:p.productId, salesModeId:'WHOLESALE',
                     price:(p.wholesalePrice != null && p.wholesalePrice.toString().trim() != '' ? (p.wholesalePrice as BigDecimal) : null),
                     thresholdQty:thBd]).call()
    ec.service.sync().name("zenith.pos.PosServices.set#PosModePrice")
        .parameters([productId:p.productId, salesModeId:extraId, price:emBd]).call()
    if (ec.message.hasError()) { def em = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:em]); return }
    // ZE-INV-001 f/u: soft warning (NOT a block — it can be legitimate). Wholesale/Custom are
    // normally <= retail; if either is higher it's usually a typo, so save but flag whichever is.
    // Retail = product MRP; if retail wasn't changed this save, compare against the current mrpAmount.
    def effRetail = rtBd
    if (effRetail == null) { def _pr = ec.entity.find("mantle.product.Product").condition("productId", p.productId).one(); effRetail = (_pr?.mrpAmount != null) ? (_pr.mrpAmount as BigDecimal) : null }
    def warn = null
    if (effRetail != null && effRetail > 0G) {
        def _hi = []
        if (wsBd != null && wsBd > 0G && wsBd > effRetail) _hi.add("Wholesale (₹" + wsBd.stripTrailingZeros().toPlainString() + ")")
        if (emBd != null && emBd > 0G && emBd > effRetail) _hi.add((extraMode.modeName ?: 'Custom') + " (₹" + emBd.stripTrailingZeros().toPlainString() + ")")
        if (_hi) warn = "Saved — but " + _hi.join(" and ") + (_hi.size() > 1 ? " are" : " is") + " higher than Retail (₹" + effRetail.stripTrailingZeros().toPlainString() + "). Wholesale/Custom are usually lower than Retail — please double-check."
    }
    ec.web.sendJsonResponse([success:true, warning:warn])
} catch (Exception e) { ec.web.sendJsonResponse([success:false, error:e.message]) }

def p = ec.web.parameters
def _searchTerm = p.searchTerm; def _catId = p.catId; def _pricingStatus = p.pricingStatus; def _gstFilter = p.gstFilter
def posOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
def extraId = (p.extraModeId ?: 'EMPLOYEE').toString()
def extraMode = ec.entity.find('zenith.erp.pos.PosSalesMode').condition('salesModeId',extraId).one()
if (!extraMode || extraMode.priceSource != 'PpsFixedProduct' || extraMode.isActive != 'Y' || extraId == 'WHOLESALE' || (extraMode.organizationPartyId && extraMode.organizationPartyId != posOrg)) { extraId = 'EMPLOYEE'; extraMode = ec.entity.find('zenith.erp.pos.PosSalesMode').condition('salesModeId',extraId).one() }
def catPIds = null
if (_catId) { catPIds = [] as Set; ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productCategoryId", _catId).list().each { catPIds.add(it.productId) } }
def slab = [:]; try { ec.entity.find("zenith.erp.india.IndiaGstSlab").list().each { slab[it.gstSlabId] = it.gstRate } } catch (Exception ig) {}
def rateSlab = { pr -> (pr.gstSlabId && slab[pr.gstSlabId] != null) ? (slab[pr.gstSlabId] as BigDecimal) : null }
def pf = ec.entity.find("mantle.product.Product").condition("productTypeEnumId", "PtAsset")
if (posOrg) pf.condition("ownerPartyId", posOrg)
def cands = pf.orderBy("productName").limit(5000).list()
def tl = (_searchTerm ?: '').toLowerCase().trim()
def fl = cands.findAll { pr ->
    (tl == '' || (pr.productName ?: '').toLowerCase().contains(tl) || (pr.pseudoId ?: '').toLowerCase().contains(tl)) &&
    (catPIds == null || catPIds.contains(pr.productId)) &&
    (_pricingStatus != 'with' || (pr.mrpAmount != null && (pr.mrpAmount as BigDecimal) > 0G)) &&
    (_pricingStatus != 'without' || pr.mrpAmount == null || (pr.mrpAmount as BigDecimal) <= 0G) &&
    (!_gstFilter || (rateSlab(pr) != null && rateSlab(pr).stripTrailingZeros().toPlainString() == _gstFilter))
}
def ids = fl.collect { it.productId }
def wM = [:]; def eM = [:]; def wT = [:]
if (ids) { ec.entity.find("zenith.erp.pos.PosProductModePrice").condition("productId", "in", ids).list().each { mp ->
    if (mp.salesModeId == 'WHOLESALE') { wM[mp.productId] = mp.price; wT[mp.productId] = mp.thresholdQty } else if (mp.salesModeId == extraId) eM[mp.productId] = mp.price } }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def bd = { v -> v == null ? "" : (v as BigDecimal).stripTrailingZeros().toPlainString() }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Product Pricing (all prices are BEFORE GST)\n")
csv.append("Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("#,Product Name,SKU,GST %,Retail (Before GST),Wholesale (Before GST),Auto-WS Qty,${esc(extraMode?.modeName ?: 'Custom')} (Before GST)\n")
int i = 0
fl.each { pr -> i++; def rt = rateSlab(pr)
    csv.append("${i},${esc(pr.productName ?: pr.productId)},${esc(pr.pseudoId ?: '')},${rt != null ? rt.stripTrailingZeros().toPlainString()+'%' : ''},${bd(pr.mrpAmount)},${bd(wM[pr.productId])},${bd(wT[pr.productId])},${bd(eM[pr.productId])}\n") }
ec.web.sendTextResponse(csv.toString(), "text/csv", "Product_Pricing_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")

def posOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
extraModeChoices = ec.entity.find('zenith.erp.pos.PosSalesMode').condition('isActive','Y').condition('priceSource','PpsFixedProduct').orderBy('modeName').list()
    .findAll { it.salesModeId != 'WHOLESALE' && (!it.organizationPartyId || it.organizationPartyId == posOrg) }
selectedExtraMode = extraModeChoices.find { it.salesModeId == extraModeId } ?: extraModeChoices.find { it.salesModeId == 'EMPLOYEE' } ?: (extraModeChoices ? extraModeChoices[0] : null)
selectedExtraModeId = selectedExtraMode?.salesModeId ?: ''
selectedExtraModeName = selectedExtraMode?.modeName ?: 'Additional mode'
// Root-relative app base ("/apps" | "/qapps" | "/vapps") for the cross-module "Add Product" link.
def _uri = (ec.web?.request?.requestURI ?: '')
def _zi = _uri.indexOf('/zenith/')
appBase = _zi > 0 ? _uri.substring(0, _zi) : ''
def pageSize = 60
def pIdx = 0
try { if (pageIndex) pIdx = (pageIndex as Integer) } catch (Exception ig) { pIdx = 0 }
if (pIdx < 0) pIdx = 0

// Categories for the filter dropdown (tenant-scoped when an org is active).
def catFinder = ec.entity.find("mantle.product.category.ProductCategory")
if (posOrg) catFinder.condition("ownerPartyId", posOrg)
categories = catFinder.orderBy("categoryName").list()

// Product ids that belong to the selected category (if filtering).
def catProdIds = null
if (catId) {
    catProdIds = [] as Set
    ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productCategoryId", catId).list().each { catProdIds.add(it.productId) }
}

// Load candidate products (tenant-scoped), then filter by search/category in memory.
def pf = ec.entity.find("mantle.product.Product").condition("productTypeEnumId", "PtAsset")
if (posOrg) pf.condition("ownerPartyId", posOrg)
def candidates = pf.orderBy("productName").limit(5000).list()
// GST slab -> rate map (used by the GST filter, the average-GST stat card, and the rows; cheap, no HSN fallback).
def slabRates = [:]
try { ec.entity.find("zenith.erp.india.IndiaGstSlab").list().each { slabRates[it.gstSlabId] = it.gstRate } } catch (Exception ig) {}
def rateSlabOf = { pr -> (pr.gstSlabId && slabRates[pr.gstSlabId] != null) ? (slabRates[pr.gstSlabId] as BigDecimal) : null }
def termLower = (searchTerm ?: '').toLowerCase().trim()
def filtered = candidates.findAll { pr ->
    (termLower == '' || (pr.productName ?: '').toLowerCase().contains(termLower) || (pr.pseudoId ?: '').toLowerCase().contains(termLower)) &&
    (catProdIds == null || catProdIds.contains(pr.productId)) &&
    (pricingStatus != 'with' || (pr.mrpAmount != null && (pr.mrpAmount as BigDecimal) > 0G)) &&
    (pricingStatus != 'without' || pr.mrpAmount == null || (pr.mrpAmount as BigDecimal) <= 0G) &&
    (!gstFilter || (rateSlabOf(pr) != null && rateSlabOf(pr).stripTrailingZeros().toPlainString() == gstFilter))
}
// distinct GST rates present (for the 'More Filters' GST dropdown), ascending as plain strings.
distinctGstRates = candidates.collect { rateSlabOf(it) }.findAll { it != null }.unique().sort().collect { it.stripTrailingZeros().toPlainString() }
totalCount = filtered.size()
pageCount = (int) Math.ceil(totalCount / (double) pageSize)
if (pageCount < 1) pageCount = 1
if (pIdx >= pageCount) pIdx = pageCount - 1
curPage = pIdx
def from = pIdx * pageSize
def to = Math.min(from + pageSize, totalCount)
def pageProds = (from < totalCount) ? filtered.subList(from, to) : []

// Existing wholesale/employee prices for the page's products.
def pageIds = pageProds.collect { it.productId }
def wMap = [:]; def eMap = [:]; def wThr = [:]
if (pageIds) {
    ec.entity.find("zenith.erp.pos.PosProductModePrice").condition("productId", "in", pageIds).list().each { mp ->
        if (mp.salesModeId == 'WHOLESALE') { wMap[mp.productId] = mp.price; wThr[mp.productId] = mp.thresholdQty }
        else if (mp.salesModeId == selectedExtraModeId) eMap[mp.productId] = mp.price
    }
}
// Each product's GST rate (prices are GST-EXCLUSIVE -> the customer pays price + this %).
// Resolve the product's configured GST slab -> rate; blank if not GST-rated. (slabRates loaded above.)
def rateOf = { pr ->
    def sid = pr.gstSlabId
    if (!sid && (pr.hsnCode ?: pr.productTaxCode)) {
        try { sid = ec.entity.find("zenith.erp.india.IndiaHsnCode").condition("hsnCode", (pr.hsnCode ?: pr.productTaxCode)).one()?.defaultGstSlabId } catch (Exception ig) {}
    }
    (sid && slabRates[sid] != null) ? (slabRates[sid] as BigDecimal) : null
}
rows = pageProds.collect { pr -> def _r = rateOf(pr); [productId: pr.productId, pseudoId: (pr.pseudoId ?: ''), productName: (pr.productName ?: pr.productId),
                                  retail: (pr.mrpAmount != null ? (pr.mrpAmount as BigDecimal).toPlainString() : ''),
                                  wholesale: (wMap[pr.productId] != null ? (wMap[pr.productId] as BigDecimal).toPlainString() : ''),
                                  wholesaleThreshold: (wThr[pr.productId] != null ? (wThr[pr.productId] as BigDecimal).stripTrailingZeros().toPlainString() : ''),
                                  employee: (eMap[pr.productId] != null ? (eMap[pr.productId] as BigDecimal).toPlainString() : ''),
                                  gstRate: (_r != null ? _r.stripTrailingZeros().toPlainString() : '')] }

// --- KPI aggregates for the stat cards (read-only; in-memory over the filtered set) ---
def _withPricing = filtered.count { it.mrpAmount != null && (it.mrpAmount as BigDecimal) > 0G }
def _gv = filtered.collect { pr -> (pr.gstSlabId && slabRates[pr.gstSlabId] != null) ? (slabRates[pr.gstSlabId] as BigDecimal) : null }.findAll { it != null }
totalDisp = String.format("%,d", (int) totalCount)
withDisp = String.format("%,d", (int) _withPricing)
withoutDisp = String.format("%,d", (int) (totalCount - _withPricing))
avgGstDisp = _gv ? (((_gv.sum() as BigDecimal) / _gv.size()).setScale(0, java.math.RoundingMode.HALF_UP)).toString() : ''
pageBase = curPage * pageSize
showFrom = totalCount == 0 ? 0 : (pageBase + 1)
showTo = Math.min(pageBase + pageProds.size(), totalCount)
